# Generated by Devo (Lead Developer)
import asyncio
import aiohttp
from typing import List
from .base import ScannerPlugin, Finding, Severity

class HTTPHeaderAuditPlugin(ScannerPlugin):
    """
    Analyzes HTTP response headers for missing security controls.
    """
    @property
    def plugin_id(self) -> str:
        return "HTTP_AUDIT_01"

    REQUIRED_HEADERS = {
        "Content-Security-Policy": "Prevents XSS and data injection attacks.",
        "X-Frame-Options": "Prevents clickjacking attacks.",
        "Strict-Transport-Security": "Enforces HTTPS connections.",
        "X-Content-Type-Options": "Prevents MIME-type sniffing."
    }

    async def run(self, target: str) -> List[Finding]:
        findings = []
        url = target if target.startswith("http") else f"http://{target}"
        
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(url, timeout=5) as response:
                    headers = response.headers
                    for header, desc in self.REQUIRED_HEADERS.items():
                        if header not in headers:
                            findings.append(Finding(
                                plugin_id=self.plugin_id,
                                severity=Severity.LOW,
                                title=f"Missing Security Header: {header}",
                                description=desc,
                                evidence=f"Header {header} not found in response from {url}",
                                remediation=f"Implement the {header} header in the web server configuration."
                            ))
        except Exception as e:
            # Log error but don't crash the engine
            return [Finding(
                plugin_id=self.plugin_id,
                severity=Severity.INFO,
                title="HTTP Audit Failed",
                description=f"Could not connect to target: {str(e)}",
                evidence=str(e),
                remediation="Ensure the target is reachable via HTTP/HTTPS."
            )]
        
        return findings